22	test("成功-1：等待期间改成另一个名字，结果只更新已提交的分派，草稿（含首尾空白）原样保留且不自动二次分派", async () => {
23	  const { h, ticket } = await setup();
24	  try {
25	    await setAssignee(h, "王芳");
26	    await submitAndWaitHeld(h);
27	    const held = h.proxy.heldBody();
28	    assert.equal(held.assignee, "王芳");
29	    assert.ok(held.operationId, "提交应携带非空操作标识");
30	
31	    // 等待结果期间把输入改成另一个名字，保留首尾空白。
32	    await setAssignee(h, "  李静  ");
33	
34	    const resp = await h.proxy.releaseNext("forward");
35	    assert.equal(resp.body.changed, true, "首次分派负责人应实际变化");
36	    const serverTicket = resp.body.ticket;
37	
38	    const s = await waitSettled(h);
39	
40	    // 列表显示服务确认的实际负责人与最近处理时间，而不是草稿。
41	    const row = rowOf(s, ticket.id);
42	    assert.equal(row.assignee, "王芳");
43	    assert.equal(row.updated, fmtMinute(serverTicket.updatedAt));
44	    // 详情同样显示服务确认的负责人、最近处理时间与分派记录。
45	    assert.equal(s.fields["负责人"], "王芳");
46	    assert.equal(s.fields["最近处理时间"], fmtMinute(serverTicket.updatedAt));
47	    assert.equal(s.history.length, 1);
48	    assert.match(s.history[0], /^未分派 → 王芳 /);
49	
50	    // 输入框保留返回时的原始内容，包括首尾空白；不被已分派负责人填回。
51	    assert.equal(s.input, "  李静  ");
52	    // 成功提示先讲清实际分派给谁，再说明输入框内容尚未提交。
53	    assert.equal(s.notice.kind, "ok");
54	    assert.match(s.notice.text, /分派成功，本次实际分派给：王芳/);
55	    assert.match(s.notice.text, /输入框中的当前内容尚未提交，已原样保留（包括首尾空白）/);
56	    // 按钮恢复可用，由用户决定是否继续提交。
57	    assert.deepEqual(s.button, { disabled: false, text: "提交分派" });
58	
59	    // 不能自动把后来填写的名字再次分派：服务端只收到王芳那次请求。
60	    const heldAfter = await waitQuiet(h);
61	    assert.equal(heldAfter, 0, "等待结束后不应自动发出第二次分派");
62	    const arrivals = h.proxy.arrivals();
63	    assert.equal(arrivals.length, 1);
64	    assert.equal(arrivals[0].assignee, "王芳");
65	    const persisted = await apiTicket(h, ticket.id);
66	    assert.equal(persisted.assignee, "王芳");
67	    assert.equal(persisted.assignments.length, 1);
68	
69	    // 用户主动再次提交草稿（输入框中仍是“  李静  ”）：新名字正常分派；
70	    // 此次等待期间未再编辑，成功后按现有行为清空输入。
71	    await submitAndWaitHeld(h);
72	    const second = h.proxy.arrivals();
73	    assert.equal(second.length, 2);
74	    assert.equal(second[1].assignee, "李静", "再次提交按去除首尾空白后的负责人发送");
75	    assert.notEqual(second[1].operationId, second[0].operationId, "成功后的下一次分派应使用新操作标识");
76	    await h.proxy.releaseNext("forward");
77	    const s2 = await waitSettled(h);
78	    assert.equal(s2.input, "", "等待期间未编辑，成功后应沿用清空输入的现有行为");
79	    assert.equal(s2.fields["负责人"], "李静");
80	    assert.equal(s2.history.length, 2);
81	    assert.match(s2.history[0], /^未分派 → 王芳 /);
82	    assert.match(s2.history[1], /^王芳 → 李静 /);
83	  } finally {
84	    await h.close();
85	  }
86	});
